// Bump Android compile/target SDK to 35 (Google Play targetSdk 35 policy).
// android/ is regenerated by `cap add android`, so this runs after cap sync
// (CI) — and can be run locally — to patch the regenerated gradle files.
// minSdk is left unchanged. No app/feature change.
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, 'android');
const TARGET = 35;

// 1) variables.gradle — compile/target SDK (Capacitor's source of these values)
const vf = path.join(root, 'variables.gradle');
let v = fs.readFileSync(vf, 'utf8');
v = v.replace(/compileSdkVersion\s*=\s*\d+/, `compileSdkVersion = ${TARGET}`);
v = v.replace(/targetSdkVersion\s*=\s*\d+/, `targetSdkVersion = ${TARGET}`);
fs.writeFileSync(vf, v);

// 2) gradle.properties — let AGP 8.2.x compile against API 35 (it was tested up
//    to 34; this flag suppresses the otherwise-fatal "unsupported compileSdk").
const gp = path.join(root, 'gradle.properties');
let g = fs.readFileSync(gp, 'utf8');
if (!/android\.suppressUnsupportedCompileSdk/.test(g)) {
  g = g.replace(/\s*$/, '') +
    `\n# Build compileSdk ${TARGET} on the bundled AGP (Play targetSdk ${TARGET} policy).\n` +
    `android.suppressUnsupportedCompileSdk=${TARGET}\n`;
  fs.writeFileSync(gp, g);
}

console.log(`Android SDK patched → compileSdk/targetSdk = ${TARGET} (minSdk unchanged)`);
console.log(v.match(/(min|compile|target)SdkVersion\s*=\s*\d+/g).join('  '));
